import json
import os
import re
import subprocess
import sys
from pathlib import Path

repo = Path.cwd()
fixture = 'qpu_barrier_syncthreads'
state_root = Path('.vc4_auto/codegen_m2')
support_script = repo / 'compiler/test/CodeGen/VC4/Support/run_candidate_codegen_test.sh'
fixture_input = repo / 'compiler/test/CodeGen/VC4/Hardware/Run' / fixture / 'input.mlir'
bundle = repo / state_root / 'candidates' / fixture
failures = []

def rel(path):
    path = Path(path)
    try:
        return str(path.resolve().relative_to(repo.resolve()))
    except Exception:
        return str(path)

def read_text(path):
    path = Path(path)
    if not path.exists():
        return ''
    return path.read_text(encoding='utf-8', errors='replace')

if not support_script.exists():
    print('missing support generate script: ' + rel(support_script))
    sys.exit(1)

env = os.environ.copy()
env['VC4_CODEGEN_STATE_ROOT'] = str(state_root)
result = subprocess.run(
    ['bash', str(support_script), fixture, 'generate'],
    cwd=repo,
    env=env,
    text=True,
    stdout=subprocess.PIPE,
    stderr=subprocess.PIPE,
)
if result.returncode != 0:
    if not fixture_input.exists():
        print('missing fixture input: ' + rel(fixture_input))
    print(f'{fixture} generate failed with exit_code={result.returncode}')
    for label, text in [('stdout', result.stdout), ('stderr', result.stderr)]:
        tail = '\n'.join(text.splitlines()[-20:])
        if tail:
            print(label + '_tail:\n' + tail)
    sys.exit(1)

manifest_path = bundle / 'manifest.json'
launch_c_path = bundle / 'kernel_launch.c'
launch_h_path = bundle / 'kernel_launch.h'
for path in [manifest_path, launch_c_path, launch_h_path]:
    if not path.exists():
        failures.append('missing generated file: ' + rel(path))

manifest = {}
if manifest_path.exists():
    try:
        manifest = json.loads(read_text(manifest_path))
    except Exception as exc:
        failures.append('manifest is not valid JSON: ' + str(exc))

kernel = None
resources = {}
kernels = manifest.get('kernels') if isinstance(manifest.get('kernels'), list) else []
if manifest_path.exists() and manifest and not kernels:
    failures.append('manifest kernels[] missing or empty')
if kernels:
    kernel = next((k for k in kernels if isinstance(k, dict) and k.get('public_name') == fixture), None)
    if kernel is None:
        failures.append('missing manifest kernel: ' + fixture)
    else:
        resources = kernel.get('resources') if isinstance(kernel.get('resources'), dict) else {}
        if kernel.get('schedule_mode') != 'cooperative_block':
            failures.append('manifest field schedule_mode expected cooperative_block, got ' + repr(kernel.get('schedule_mode')))
        if resources.get('uses_barrier') is not True:
            failures.append('manifest field resources.uses_barrier expected true, got ' + repr(resources.get('uses_barrier')))
        if resources.get('require_full_block_residency') is not True:
            failures.append('manifest field resources.require_full_block_residency expected true, got ' + repr(resources.get('require_full_block_residency')))
        if 'warps_per_block_max' not in resources:
            failures.append('missing manifest field resources.warps_per_block_max')
        else:
            try:
                warps = int(resources.get('warps_per_block_max'))
                if warps > 12:
                    failures.append('manifest field resources.warps_per_block_max expected <= 12, got ' + str(warps))
            except Exception:
                failures.append('manifest field resources.warps_per_block_max is not an integer: ' + repr(resources.get('warps_per_block_max')))
        if resources.get('semaphores_per_block') != 4:
            failures.append('manifest field resources.semaphores_per_block expected 4, got ' + repr(resources.get('semaphores_per_block')))
        if resources.get('uses_shared_vpm') is True and 'vpm_bytes_per_block' not in resources and 'vpm_rows_per_block' not in resources:
            failures.append('missing manifest field resources.vpm_bytes_per_block or resources.vpm_rows_per_block when resources.uses_shared_vpm is true')

launch_text = read_text(launch_h_path) + '\n' + read_text(launch_c_path)
if launch_text:
    if not re.search(r'VC4_KERNEL_SCHEDULE_COOPERATIVE_BLOCK|VC4_KERNEL_FLAG_COOPERATIVE_BLOCK|VC4_[A-Z0-9_]*COOPERATIVE[A-Z0-9_]*BLOCK', launch_text):
        failures.append('missing generated runtime cooperative schedule enum/flag: VC4_KERNEL_SCHEDULE_COOPERATIVE_BLOCK or equivalent')
    if not re.search(r'\bqpu_barrier_syncthreads_pack_uniforms\s*\(', launch_text):
        failures.append('missing generated runtime function: qpu_barrier_syncthreads_pack_uniforms')
    if not re.search(r'\bvc4LaunchKernel\s*\(|\bvc4LaunchCooperative\w*\s*\(', launch_text):
        failures.append('missing generated runtime launcher entrypoint: vc4LaunchKernel or cooperative runtime entrypoint')
    if re.search(r'physical_qpu_indexing', launch_text):
        failures.append('forbidden generated runtime token present: physical_qpu_indexing')
    if ('#define VC4_KERNEL_SCHEDULE_COOPERATIVE_BLOCK ' + 'VC4_KERNEL_SCHEDULE_INDEPENDENT_VECTOR') in launch_text:
        failures.append('forbidden generated runtime cooperative-to-independent schedule alias')

runtime_paths = [
    repo / 'compiler/test/CodeGen/VC4/Runtime/vc4_runtime.c',
    repo / 'compiler/test/CodeGen/VC4/Runtime/vc4_runtime.h',
    repo / 'compiler/lib/Target/VC4/VC4ArtifactEmitter.cpp',
    launch_c_path,
    launch_h_path,
]
runtime_text = '\n'.join(read_text(path) for path in runtime_paths if path.exists())
runtime_hooks = {
    'schedule_mode switch or flag check': r'\bschedule_mode\b|VC4_KERNEL_SCHEDULE|kernel_schedule',
    'resident_blocks': r'\bresident_blocks\b',
    'warps_per_block': r'\bwarps_per_block\b',
    'logical_warp_id': r'\blogical_warp_id\b',
    'vpm_base_row': r'\bvpm_base_row\b',
    'semaphore_base': r'\bsemaphore_base\b',
    'request_info packing ABI': r'vc4_launch_request_info|requestInfo',
    'full-residency wait/reuse discipline': r'full[_-]?residenc|resident[_-]?wave|wait[^\n;]*resident|resident[^\n;]*wait|reuse[^\n;]*resident|resident[^\n;]*reuse',
}
for name, pattern in runtime_hooks.items():
    if not re.search(pattern, runtime_text, flags=re.I | re.S):
        failures.append('missing runtime/source hook: ' + name)

for label, pattern in {
    'early_resource_reuse=1': r'early_resource_reuse\s*=\s*1',
    'oversubscribed_barrier=1': r'oversubscribed_barrier\s*=\s*1',
}.items():
    if re.search(pattern, runtime_text):
        failures.append('forbidden runtime/source token present: ' + label)

emitter_text = read_text(repo / 'compiler/lib/Target/VC4/VC4ArtifactEmitter.cpp')
dq = chr(34)
fixture_special_patterns = [
    r'\b(?:launchABI\.)?publicName\s*==\s*' + dq + fixture + dq,
    dq + fixture + dq + r'\s*==\s*(?:launchABI\.)?publicName',
    r'\b(?:append|emit|write)QpuBarrierSyncthreads(?:QASM|Runtime|Kernel|Launch)\b',
]
for pattern in fixture_special_patterns:
    if re.search(pattern, emitter_text):
        failures.append('forbidden fixture-name special case in VC4ArtifactEmitter.cpp: /' + pattern + '/')

if failures:
    for failure in failures:
        print(failure)
    sys.exit(1)
print('cooperative generated/runtime contract passed: ' + rel(bundle))

